"""Preserve Meridian CRM CRMScript division-by-zero behavior."""


def _numeric(value) -> float:
    """Apply legacy numeric coercion for supported operand values."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Divide using legacy coercion and SCRIPT_DIV0 audit behavior."""
    numerator = _numeric(a)
    divisor = _numeric(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return float(numerator / divisor), []
    except (ArithmeticError, OverflowError):
        return 0.0, ["SCRIPT_DIV0"]
